class Solution {
    int getNext(int i, const vector<int>& nums, int n) {
        return ((i + nums[i]) % n + n) % n;
    }
public:
    bool circularArrayLoop(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) continue;
            int slow = i;
            int fast = getNext(i, nums, n);
            bool direction = nums[i] > 0;

            while (nums[fast] != 0 && (nums[fast] > 0) == direction && (nums[getNext(fast, nums, n)] > 0) == direction) {
                if (slow == fast) {
                    if (slow == getNext(slow, nums, n)) break;
                    return true;
                }
                slow = getNext(slow, nums, n);
                fast = getNext(getNext(fast, nums, n), nums, n);
            }

            int curr = i;
            while (nums[curr] != 0 && (nums[curr] > 0) == direction) {
                int nxt = getNext(curr, nums, n);
                nums[curr] = 0;
                curr = nxt;
            }
        }
        return false;
    }
};

class Solution {
    private int getNext(int i, int[] nums, int n) {
        return ((i + nums[i]) % n + n) % n;
    }

    public boolean circularArrayLoop(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            if (nums[i] == 0) continue;
            int slow = i;
            int fast = getNext(i, nums, n);
            boolean direction = nums[i] > 0;

            while (nums[fast] != 0 && (nums[fast] > 0) == direction && (nums[getNext(fast, nums, n)] > 0) == direction) {
                if (slow == fast) {
                    if (slow == getNext(slow, nums, n)) break;
                    return true;
                }
                slow = getNext(slow, nums, n);
                fast = getNext(getNext(fast, nums, n), nums, n);
            }

            int curr = i;
            while (nums[curr] != 0 && (nums[curr] > 0) == direction) {
                int nxt = getNext(curr, nums, n);
                nums[curr] = 0;
                curr = nxt;
            }
        }
        return false;
    }
}

var circularArrayLoop = function(nums) {
    const n = nums.length;
    function getNext(i) {
        return ((i + nums[i]) % n + n) % n;
    }

    for (let i = 0; i < n; i++) {
        if (nums[i] === 0) continue;
        let slow = i;
        let fast = getNext(i);
        const direction = nums[i] > 0;

        while (nums[fast] !== 0 && (nums[fast] > 0) === direction && (nums[getNext(fast)] > 0) === direction) {
            if (slow === fast) {
                if (slow === getNext(slow)) break;
                return true;
            }
            slow = getNext(slow);
            fast = getNext(getNext(fast));
        }

        let curr = i;
        while (nums[curr] !== 0 && (nums[curr] > 0) === direction) {
            const nxt = getNext(curr);
            nums[curr] = 0;
            curr = nxt;
        }
    }
    return false;
};
